const escapeHtml = (value = '') => String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const icon = (name, size = 20) => {
  const paths = {
    book: '<path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v16H6.5A2.5 2.5 0 0 0 4 21V5.5Zm0 13A2.5 2.5 0 0 1 6.5 16H20"/>',
    grid: '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
    check: '<path d="m5 12 4 4L19 6"/>',
    plus: '<path d="M12 5v14M5 12h14"/>',
    arrow: '<path d="M5 12h14m-6-6 6 6-6 6"/>',
    left: '<path d="M19 12H5m6 6-6-6 6-6"/>',
    link: '<path d="M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7"/>',
    feather: '<path d="M20 4c-7 0-14 5-14 13l-2 3m2-3c4 0 9-4 11-8M6 17l5-5"/>',
    sparkle: '<path d="m12 2 1.8 6.2L20 10l-6.2 1.8L12 18l-1.8-6.2L4 10l6.2-1.8L12 2Zm7 14 .8 2.2L22 19l-2.2.8L19 22l-.8-2.2L16 19l2.2-.8L19 16Z"/>',
  };
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]}</svg>`;
};

const coverStyle = (book) => {
  const colors = [
    ['#c7694f', '#e9af82', '#563931'], ['#657763', '#adbaa0', '#293e37'],
    ['#506979', '#9cb5b7', '#263a47'], ['#a77c4f', '#e0bf87', '#503b2d'],
    ['#706579', '#b6a7b8', '#3e3546'], ['#a35759', '#dc9c91', '#4e3334'],
  ];
  const n = [...book.id].reduce((sum, char) => sum + char.charCodeAt(0), 0) % colors.length;
  const [base, light, dark] = colors[n];
  return `--cover:${base};--cover-light:${light};--cover-dark:${dark}`;
};

function cover(book, className = '') {
  return `<div class="cover ${className}" style="${coverStyle(book)}" aria-hidden="true"><span class="cover-mark">✳</span><span class="cover-rule"></span><span class="cover-title">${escapeHtml(book.title)}</span><span class="cover-author">${escapeHtml(book.author)}</span><span class="cover-bottom">THE READING ROOM</span></div>`;
}

function layout({ title, active = 'library', books, content }) {
  const reading = books.filter(b => b.status === 'reading').length;
  const finished = books.length - reading;
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f8f6f1"><title>${escapeHtml(title)} · The Reading Room</title><link rel="stylesheet" href="/styles.css"></head>
<body><div class="app-shell">
  <aside class="sidebar">
    <a href="/" class="brand" aria-label="The Reading Room home"><span class="brand-icon">${icon('book', 23)}</span><span>the reading<br><em>room.</em></span></a>
    <div class="sidebar-group"><div class="sidebar-label">YOUR SPACE</div><nav aria-label="Main navigation">
      <a class="nav-link ${active === 'library' ? 'active' : ''}" href="/">${icon('grid', 19)}<span>My library</span></a>
      <a class="nav-link ${active === 'new' ? 'active' : ''}" href="/new">${icon('plus', 19)}<span>Add a book</span></a>
    </nav></div>
    <div class="sidebar-bottom"><div class="sidebar-quote">“A reader lives a thousand lives before he dies.”<span>— George R. R. Martin</span></div><div class="sidebar-foot">A little space for big stories. <span>✳</span></div></div>
  </aside>
  <main class="main"><div class="main-inner">${content}<footer class="footer"><span>THE READING ROOM</span><span>Made for the stories that stay with you. ✳</span></footer></div></main>
</div><script src="/app.js" defer></script></body></html>`;
}

function readingCard(book) {
  return `<a class="reading-card" href="/books/${encodeURIComponent(book.id)}">${cover(book, 'card-cover')}<div class="reading-card-body"><span class="eyebrow">CURRENTLY READING</span><h3>${escapeHtml(book.title)}</h3><p>by ${escapeHtml(book.author)}</p><span class="text-link">View book ${icon('arrow', 17)}</span></div></a>`;
}

function finishedCard(book) {
  return `<a class="finished-card" href="/books/${encodeURIComponent(book.id)}">${cover(book, 'mini-cover')}<div class="finished-info"><h3>${escapeHtml(book.title)}</h3><p>${escapeHtml(book.author)}</p><span>Finished ${formatDate(book.finishedAt || book.createdAt)}</span></div><span class="finished-arrow">${icon('arrow', 18)}</span></a>`;
}

function formatDate(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? '' : new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(date);
}

export function home(books) {
  const reading = books.filter(b => b.status === 'reading').reverse();
  const finished = books.filter(b => b.status === 'finished').reverse();
  const content = `<header class="topline"><span class="topline-label">YOUR PERSONAL LIBRARY <span class="topline-dot">✳</span></span><span class="topline-date">${new Intl.DateTimeFormat('en', { month: 'long', year: 'numeric' }).format(new Date())}</span></header>
    <section class="page-heading"><div><div class="overline">A HOME FOR YOUR STORIES <span class="little-line"></span></div><h1>My reading <em>room.</em></h1><p>Every book has a story. Keep yours close.</p></div><a class="button button-primary heading-action" href="/new">${icon('plus', 18)} Add a book</a></section>
    <div class="stats"><div class="stat"><span class="stat-icon stat-icon-reading">${icon('book', 21)}</span><div><strong>${reading.length}</strong><span>Currently reading</span></div></div><div class="stat-divider"></div><div class="stat"><span class="stat-icon stat-icon-finished">${icon('check', 22)}</span><div><strong>${finished.length}</strong><span>Books finished</span></div></div><div class="stats-flourish" aria-hidden="true">✳</div></div>
    <section class="shelf"><div class="section-heading"><div><span class="section-index">01 / ON THE NIGHTSTAND</span><h2>Currently reading <span class="count">${reading.length}</span></h2></div></div>
      ${reading.length ? `<div class="reading-grid">${reading.map(readingCard).join('')}</div>` : `<div class="empty-state"><div class="empty-art" aria-hidden="true"><div class="art-book art-book-one"></div><div class="art-book art-book-two"></div><div class="art-book art-book-three"></div><span>✳</span></div><div><span class="eyebrow">A FRESH PAGE</span><h3>Your next chapter starts here.</h3><p>No books on your nightstand yet. Add what you're reading and let the story begin.</p><a class="text-link" href="/new">Add your first book ${icon('arrow', 17)}</a></div></div>`}
    </section>
    <section class="shelf finished-shelf"><div class="section-heading"><div><span class="section-index">02 / THE ARCHIVE</span><h2>Finished books <span class="count">${finished.length}</span></h2></div></div>
      ${finished.length ? `<div class="finished-grid">${finished.map(finishedCard).join('')}</div>` : `<div class="finished-empty">${icon('sparkle', 20)} <span>Books you've finished will find a home here.</span></div>`}
    </section>`;
  return layout({ title: 'My library', books, content });
}

export function newBook(books, error = '', values = {}) {
  const content = `<header class="topline"><span class="topline-label">YOUR PERSONAL LIBRARY <span class="topline-dot">✳</span></span><a class="topline-back" href="/">${icon('left', 16)} Back to library</a></header>
  <div class="form-layout"><div class="form-intro"><div class="overline">MAKE ROOM FOR A NEW STORY <span class="little-line"></span></div><h1>Add a <em>book.</em></h1><p>Good books deserve a place to stay. Tell us a little about this one.</p><div class="form-illustration" aria-hidden="true"><div class="illustration-page"><span>✳</span><div></div><div></div><div></div><div></div></div></div></div>
  <form class="book-form" action="/books" method="post"><div class="form-header"><span class="section-index">A NEW CHAPTER</span><h2>Book details</h2><p>Just the essentials. You can always come back to your notes.</p></div>
    ${error ? `<div class="form-error" role="alert">${escapeHtml(error)}</div>` : ''}
    <label for="title">Book title <span>*</span></label><input id="title" name="title" type="text" maxlength="200" required placeholder="e.g. The Secret History" value="${escapeHtml(values.title || '')}" autofocus>
    <label for="author">Author <span>*</span></label><input id="author" name="author" type="text" maxlength="150" required placeholder="e.g. Donna Tartt" value="${escapeHtml(values.author || '')}">
    <label for="notes">Your notes <span class="optional">OPTIONAL</span></label><textarea id="notes" name="notes" maxlength="10000" rows="6" placeholder="A thought, a quote, a feeling to remember...">${escapeHtml(values.notes || '')}</textarea><p class="field-hint">The little things you want to remember about this book.</p>
    <div class="form-actions"><button class="button button-primary" type="submit">Add to my library ${icon('arrow', 18)}</button><a href="/" class="cancel-link">Cancel</a></div>
  </form></div>`;
  return layout({ title: 'Add a book', active: 'new', books, content });
}

export function detail(book, books) {
  const finished = book.status === 'finished';
  const content = `<header class="topline"><span class="topline-label">YOUR PERSONAL LIBRARY <span class="topline-dot">✳</span></span><a class="topline-back" href="/">${icon('left', 16)} Back to library</a></header>
    <nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">My library</a><span>/</span><span>${escapeHtml(book.title)}</span></nav>
    <div class="detail-hero"><div class="detail-cover-wrap">${cover(book, 'detail-cover')}<div class="cover-caption">A STORY WORTH KEEPING <span>✳</span></div></div><div class="detail-info"><span class="status-pill ${finished ? 'status-finished' : ''}"><span class="status-dot"></span>${finished ? 'FINISHED' : 'CURRENTLY READING'}</span><h1>${escapeHtml(book.title)}</h1><p class="detail-author">by <strong>${escapeHtml(book.author)}</strong></p><div class="detail-rule"></div><div class="detail-meta"><span>ADDED TO YOUR LIBRARY</span><strong>${formatDate(book.createdAt)}</strong></div>${finished ? `<div class="detail-meta"><span>FINISHED ON</span><strong>${formatDate(book.finishedAt || book.createdAt)}</strong></div>` : ''}<div class="detail-actions">${!finished ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish"><button class="button button-primary" type="submit">${icon('check', 19)} Mark as finished</button></form>` : `<div class="finished-badge">${icon('check', 18)} Another story for the shelves</div>`}<button class="button button-outline" type="button" data-copy-link>${icon('link', 18)} <span>Copy link</span></button></div><p class="share-hint">Share this page with anyone. No account needed.</p></div></div>
    <section class="notes-section"><div class="section-heading"><div><span class="section-index">THOUGHTS & MARGINS</span><h2>My notes</h2></div>${icon('feather', 25)}</div><div class="notes-paper">${book.notes?.trim() ? `<p>${escapeHtml(book.notes).replace(/\r?\n/g, '<br>')}</p>` : `<p class="no-notes">No notes for this one yet. Some stories just speak for themselves.</p>`}</div></section>`;
  return layout({ title: book.title, books, content });
}

export function notFound(books) {
  return layout({ title: 'Page not found', books, content: `<header class="topline"><span class="topline-label">YOUR PERSONAL LIBRARY ✳</span></header><div class="not-found"><span class="overline">A PAGE OUT OF PLACE</span><h1>Lost your <em>place?</em></h1><p>We couldn't find that book. It may have wandered off the shelf.</p><a class="button button-primary" href="/">${icon('left', 18)} Back to library</a></div>` });
}

