import http from 'node:http';
import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { home, newBook, detail, notFound } from './views.mjs';

const root = dirname(fileURLToPath(import.meta.url));
const dataFile = process.env.BOOKS_FILE || join(root, 'data', 'books.json');
const port = Number(process.env.PORT || 3000);
let mutation = Promise.resolve();

async function loadBooks() {
  try {
    const books = JSON.parse(await readFile(dataFile, 'utf8'));
    if (!Array.isArray(books)) throw new Error('Book data must be an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

async function saveBooks(books) {
  await mkdir(dirname(dataFile), { recursive: true });
  const temporary = `${dataFile}.${randomUUID()}.tmp`;
  await writeFile(temporary, JSON.stringify(books, null, 2) + '\n');
  await rename(temporary, dataFile);
}

function updateBooks(change) {
  const next = mutation.then(async () => {
    const books = await loadBooks();
    const result = change(books);
    if (result !== null) await saveBooks(books);
    return result;
  });
  mutation = next.catch(() => {});
  return next;
}

function send(res, status, content, type = 'text/html; charset=utf-8', headers = {}) {
  res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff', ...headers });
  res.end(content);
}
function redirect(res, path) {
  res.writeHead(303, { Location: path });
  res.end();
}
async function bodyParams(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 25000) {
      const error = new Error('Form is too large');
      error.status = 413;
      throw error;
    }
  }
  return new URLSearchParams(body);
}

export async function handle(req, res) {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && (path === '/styles.css' || path === '/app.js')) {
      const name = path === '/styles.css' ? 'styles.css' : 'app.js';
      return send(res, 200, await readFile(join(root, name)), path === '/styles.css' ? 'text/css; charset=utf-8' : 'text/javascript; charset=utf-8');
    }
    if (req.method === 'GET' && path === '/favicon.ico') return send(res, 204, '');
    const books = await loadBooks();
    if (req.method === 'GET' && path === '/') return send(res, 200, home(books));
    if (req.method === 'GET' && path === '/new') return send(res, 200, newBook(books));
    if (req.method === 'POST' && path === '/books') {
      const params = await bodyParams(req);
      const title = (params.get('title') || '').trim();
      const author = (params.get('author') || '').trim();
      const notes = (params.get('notes') || '').trim();
      if (!title || !author || title.length > 200 || author.length > 150 || notes.length > 10000) {
        return send(res, 400, newBook(books, 'Please enter a title and author within the allowed lengths.', { title, author, notes }));
      }
      const book = { id: randomUUID(), title, author, notes, status: 'reading', createdAt: new Date().toISOString(), finishedAt: null };
      await updateBooks(items => { items.push(book); return book; });
      return redirect(res, `/books/${book.id}`);
    }
    const match = /^\/books\/([a-f0-9-]+)(\/finish)?$/.exec(path);
    if (match) {
      const id = match[1];
      if (req.method === 'POST' && match[2] === '/finish') {
        const changed = await updateBooks(items => {
          const book = items.find(item => item.id === id);
          if (!book || book.status === 'finished') return null;
          book.status = 'finished';
          book.finishedAt = new Date().toISOString();
          return book;
        });
        return changed ? redirect(res, `/books/${id}`) : send(res, 404, notFound(await loadBooks()));
      }
      if (req.method === 'GET' && !match[2]) {
        const book = books.find(item => item.id === id);
        return book ? send(res, 200, detail(book, books)) : send(res, 404, notFound(books));
      }
    }
    return send(res, 404, notFound(books));
  } catch (error) {
    console.error(error);
    return send(res, error.status || 500, error.status === 413 ? 'Form is too large' : 'Something went wrong. Please try again.', 'text/plain; charset=utf-8');
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === join(process.cwd(), process.argv[1])) {
  http.createServer(handle).listen(port, () => console.log(`The Reading Room is ready at http://localhost:${port}`));
}

