      const book = { id: randomUUID(), title, author, notes, status: 'reading', createdAt: new Date().toISOString(), finishedAt: null };
      await updateBooks(items => { items.push(book); return book; });
      return redirect(res, `/books/${book.id}`);
    }
    const match = /^\/books\/([a-f0-9-]+)(\/finish)?$/.exec(path);
    if (match) {
      const id = match[1];
      if (req.method === 'POST' && match[2] === '/finish') {
        const changed = await updateBooks(items => {
          const book = items.find(item => item.id === id);
          if (!book || book.status === 'finished') return null;
          book.status = 'finished';
          book.finishedAt = new Date().toISOString();
          return book;
        });
        return changed ? redirect(res, `/books/${id}`) : send(res, 404, notFound(await loadBooks()));
      }
      if (req.method === 'GET' && !match[2]) {
        const book = books.find(item => item.id === id);
        return book ? send(res, 200, detail(book, books)) : send(res, 404, notFound(books));
      }
    }
    return send(res, 404, notFound(books));
  } catch (error) {
    console.error(error);
    return send(res, error.status || 500, error.status === 413 ? 'Form is too large' : 'Something went wrong. Please try again.', 'text/plain; charset=utf-8');
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  http.createServer(handle).listen(port, () => console.log(`The Reading Room is ready at http://localhost:${port}`));
}

