import http from 'node:http';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

function listen(handler) {
  const server = http.createServer(handler);
  return new Promise(resolve => server.listen(0, '127.0.0.1', () => resolve(server)));
}
function close(server) { return new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve())); }

test('books persist on disk, are viewable at direct links, and can be finished', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'reading-room-'));
  process.env.BOOKS_FILE = join(dir, 'books.json');
  let server;
  try {
    const { handle } = await import('./server.mjs');
    server = await listen(handle);
    let base = `http://127.0.0.1:${server.address().port}`;
    let response = await fetch(base);
    assert.equal(response.status, 200);
    assert.match(await response.text(), /Your next chapter starts here/);

    response = await fetch(`${base}/books`, { method: 'POST', body: new URLSearchParams({ title: '<The Book>', author: 'A. Writer', notes: 'A note & more\nAnother thought' }), redirect: 'manual' });
    assert.equal(response.status, 303);
    const location = response.headers.get('location');
    assert.match(location, /^\/books\/[a-f0-9-]+$/);
    response = await fetch(base + location);
    const page = await response.text();
    assert.match(page, /&lt;The Book&gt;/);
    assert.doesNotMatch(page, /<The Book>/);
    assert.match(page, /A note &amp; more<br>Another thought/);
    assert.match(page, /Mark as finished/);

    const raw = JSON.parse(await readFile(process.env.BOOKS_FILE, 'utf8'));
    assert.equal(raw.length, 1);
    assert.equal(raw[0].status, 'reading');
    await close(server); server = null;
    server = await listen(handle);
    base = `http://127.0.0.1:${server.address().port}`;
    response = await fetch(base + location);
    assert.equal(response.status, 200);
    assert.match(await response.text(), /A note &amp; more/);

    response = await fetch(`${base}${location}/finish`, { method: 'POST', redirect: 'manual' });
    assert.equal(response.status, 303);
    response = await fetch(base);
    const home = await response.text();
    assert.match(home, /Finished books/);
    assert.match(home, /&lt;The Book&gt;/);
    assert.equal(JSON.parse(await readFile(process.env.BOOKS_FILE, 'utf8'))[0].status, 'finished');
    response = await fetch(`${base}/books/00000000-0000-0000-0000-000000000000`);
    assert.equal(response.status, 404);
  } finally {
    if (server) await close(server);
    await rm(dir, { recursive: true, force: true });
    delete process.env.BOOKS_FILE;
  }
});

